/**
 *
 * DataTableSortIndicator displays a visual indicator for the sort state of a DataTable column.
 * Must be used inside DataTable.Sort. Uses `match` prop for conditional visibility.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableSortIndicator
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
/**
 * Defines passthrough(pt) options type in DataTableSortIndicator component.
 */
export type DataTableSortIndicatorPassThroughType<E> = PassThroughType<DataTableSortIndicatorInstance, E>;
/**
 * Defines passthrough(pt) options of DataTableSortIndicator component.
 */
export interface DataTableSortIndicatorPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTableSortIndicatorPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
/**
 * Defines valid properties in DataTableSortIndicator component.
 */
export interface DataTableSortIndicatorProps extends BaseComponentProps<DataTableSortIndicatorInstance, unknown, DataTableSortIndicatorPassThrough, 'span'> {
    /**
     * Determines the visibility of the indicator based on the sort state.
     * - "asc": Visible when sorted ascending.
     * - "desc": Visible when sorted descending.
     * - "unsorted": Visible when not sorted (useful with removableSort).
     * - "always": Indicator is always visible.
     * @defaultValue 'always'
     */
    match?: 'asc' | 'desc' | 'unsorted' | 'always' | undefined;
}
/**
 * Defines valid state in DataTableSortIndicator component.
 */
export interface DataTableSortIndicatorState {
}
/**
 * Defines the methods and properties exposed by DataTableSortIndicator component.
 */
export interface DataTableSortIndicatorExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
}
/**
 * Instance of DataTableSortIndicator component.
 */
export type DataTableSortIndicatorInstance = ComponentInstance<DataTableSortIndicatorProps, DataTableSortIndicatorState, DataTableSortIndicatorExposes>;
